css:
.mp-page { height: 100dvh; overflow: hidden; display: grid; grid-template-rows: auto 1fr auto; gap: clamp(12px, 2vh, 24px); padding: clamp(20px, 4vh, 48px); background: var(--mp-panel); color: var(--mp-ink); }
.mp-head { display: grid; gap: 8px; }
h1 { margin: 0; font-size: clamp(22px, 3.2vw, 40px); line-height: 1.2; letter-spacing: -0.01em; }
.mp-sub { margin: 0; color: var(--mp-muted); font-size: clamp(13px, 1.4vw, 18px); }
.mp-body { display: grid; place-content: center; gap: 12px; border: 1px solid var(--mp-border); border-radius: 16px; background: var(--mp-raised); padding: clamp(16px, 3vh, 32px); }
.mp-range { margin: 0; font-family: var(--mp-font-mono); font-size: clamp(16px, 2vw, 28px); }
.mp-hint { margin: 0; color: var(--mp-muted); font-size: clamp(12px, 1.2vw, 15px); }
.mp-foot { display: flex; justify-content: flex-end; }
.mp-btn { border: 1px solid var(--mp-border-strong); background: var(--mp-invert); color: var(--mp-invert-ink); border-radius: 999px; padding: 10px 20px; font-size: 15px; cursor: pointer; }
.mp-page[data-mp-state="hit"] .mp-range { color: var(--mp-invert); }
@media (prefers-reduced-motion: reduce) { .mp-btn { transition: none; } }

js:
(function () {
  var root = document.querySelector('.mp-page');
  var range = root.querySelector('[data-mp-role="range"]');
  var button = root.querySelector("[data-mp-action='step']");
  var steps = 0;
  var left = 1;
  var right = 16;
  button.addEventListener('click', function () {
    steps += 1;
    var mid = Math.floor((left + right) / 2);
    range.textContent = '当前区间：[' + (mid + 1) + ', ' + right + ']';
    root.dataset.mpState = steps >= 3 ? 'hit' : 'searching';
    MockFinal.emit('interaction', { id: 'bisect-step', step: steps });
  });
  MockFinal.ready({ title: '二分查找：每次排除一半' });
})();
